integrations/claude/settings-hooks.json.template:
{
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume|clear|compact",
        "hooks": [
          {
            "type": "command",
            "command": "@HOME@/.local/bin/muninn hook session-start --provider claude",
            "timeout": 5
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "@HOME@/.local/bin/muninn hook prompt --provider claude",
            "timeout": 5
          }
        ]
      }
    ]
  }
}

integrations/codex/hooks/hooks.json.template:
{
  "description": "Inject bounded muninn memory blocks as untrusted data.",
  "hooks": {
    "SessionStart": [
      {
        "matcher": "startup|resume|clear|compact",
        "hooks": [
          {
            "type": "command",
            "command": "@HOME@/.local/bin/muninn hook session-start --provider codex",
            "timeout": 5,
            "additionalContextLimit": 1500
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "@HOME@/.local/bin/muninn hook prompt --provider codex",
            "timeout": 5,
            "additionalContextLimit": 500
          }
        ]
      }
    ]
  }
}
